## lang attribute

```html
<!-- Primary language of this page -->
<html lang="en">

<!-- Specific variant -->
<html lang="en-GB">
<html lang="tr">
<html lang="ar" dir="rtl">
```

## hreflang for alternate versions

```html
<head>
  <!-- Tell search engines all language variants -->
  <link rel="alternate" hreflang="en" href="https://example.com/en/about" />
  <link rel="alternate" hreflang="tr" href="https://example.com/tr/about" />
  <link rel="alternate" hreflang="ar" href="https://example.com/ar/about" />
  <!-- x-default: fallback for unmatched locales -->
  <link rel="alternate" hreflang="x-default" href="https://example.com/about" />
</head>
```

## Next.js App Router i18n

```
src/app/
  [locale]/
    layout.tsx   ← sets <html lang={locale}>
    page.tsx
    about/
      page.tsx
```

```tsx
// app/[locale]/layout.tsx
export default function RootLayout({ children, params: { locale } }) {
  const isRTL = ['ar', 'he', 'fa'].includes(locale);
  return (
    <html lang={locale} dir={isRTL ? 'rtl' : 'ltr'}>
      <body>{children}</body>
    </html>
  );
}
```

## Accept-Language header

```ts
// middleware.ts — redirect to locale based on browser preference
import { match } from '@formatjs/intl-localematcher';
import Negotiator from 'negotiator';

const locales = ['en', 'tr', 'ar'];
const defaultLocale = 'en';

export function middleware(request: Request) {
  const headers = { 'accept-language': request.headers.get('accept-language') ?? '' };
  const languages = new Negotiator({ headers }).languages();
  const locale = match(languages, locales, defaultLocale);
  return Response.redirect(new URL(`/${locale}${request.nextUrl.pathname}`, request.url));
}
```
